mapper.select:
select
    (select COUNT(*) from Sec_Expert_Audit_Detail ead where ead.Sea_Id=mn.id) as detailCount,
    mn.*
from Sec_Expert_Audit mn

    
        and mn.year=#{params.year}
    
    
        and mn.Te_Id=#{params.teId}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Sea_Name,#{params.seaName})
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and mn.Sea_Cid=#{params.seaCid}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
